import{_ as t,o as a,c as r,a4 as n}from"./chunks/framework.DuWKp7Dh.js";const u=JSON.parse('{"title":"ADR-010: Headless parser and document architecture for the code editor","description":"","frontmatter":{},"headers":[],"relativePath":"reference/decisions/ADR-010-code-editor-headless-architecture.md","filePath":"reference/decisions/ADR-010-code-editor-headless-architecture.md"}'),o={name:"reference/decisions/ADR-010-code-editor-headless-architecture.md"};function i(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-010-headless-parser-and-document-architecture-for-the-code-editor" tabindex="-1">ADR-010: Headless parser and document architecture for the code editor <a class="header-anchor" href="#adr-010-headless-parser-and-document-architecture-for-the-code-editor" aria-label="Permalink to &quot;ADR-010: Headless parser and document architecture for the code editor&quot;">​</a></h1><blockquote><p><strong>Date</strong>: 2026-07-24 <strong>Last Updated</strong>: 2026-07-24 <strong>Status</strong>: Accepted</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The terminal-native code editor needs an efficient text model, JavaScript, TypeScript, and PostgreSQL parsing, and Language Server Protocol types without a browser, DOM, or IDE runtime. Library documentation alone cannot prove import isolation, dependency closure, scheduling behavior, or interactive latency.</p><p>The architecture probe evaluated built public package entry points in separate Node 22 processes, exercised representative edits and parsers, inspected every installed production dependency instance and license, and measured document edit-plus-viewport projection for one-mebibyte and fifty-thousand-line fixtures.</p><h2 id="options-considered" tabindex="-1">Options Considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options Considered&quot;">​</a></h2><h3 id="option-a-codemirror-state-and-language-packages" tabindex="-1">Option A: CodeMirror state and language packages <a class="header-anchor" href="#option-a-codemirror-state-and-language-packages" aria-label="Permalink to &quot;Option A: CodeMirror state and language packages&quot;">​</a></h3><ul><li><strong>Pros</strong>: Cohesive APIs and mature parsers.</li><li><strong>Cons</strong>: The language wrappers ship <code>@codemirror/view</code>, introducing a DOM-oriented runtime dependency even when the editor does not import a browser view.</li></ul><h3 id="option-b-public-headless-packages-behind-editor-owned-contracts" tabindex="-1">Option B: Public headless packages behind editor-owned contracts <a class="header-anchor" href="#option-b-public-headless-packages-behind-editor-owned-contracts" aria-label="Permalink to &quot;Option B: Public headless packages behind editor-owned contracts&quot;">​</a></h3><ul><li><strong>Pros</strong>: Keeps the dependency closure terminal-safe and makes each parser replaceable.</li><li><strong>Cons</strong>: PostgreSQL and Lezer results require separate adapter implementations.</li></ul><h3 id="option-c-custom-text-model-and-grammars" tabindex="-1">Option C: Custom text model and grammars <a class="header-anchor" href="#option-c-custom-text-model-and-grammars" aria-label="Permalink to &quot;Option C: Custom text model and grammars&quot;">​</a></h3><ul><li><strong>Pros</strong>: Complete control over behavior and dependencies.</li><li><strong>Cons</strong>: Substantially larger correctness, security, performance, and maintenance burden.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use <code>@codemirror/state</code> <code>Text</code> and <code>ChangeSet</code> internally for document storage and mapping. Use <code>@lezer/javascript</code> directly for JavaScript and TypeScript. Use <code>pgsql-ast-parser</code> behind the PostgreSQL adapter, with revision-stamped cancellable background work and bounded lexical presentation while a parse is pending. Use official <code>vscode-languageserver-protocol</code> types behind an editor-owned transport-neutral session.</p><p>Do not ship CodeMirror language or view packages. Parser-specific types remain internal to their adapters. The indexed piece-tree document model remains the fallback if later document or memory probes breach their hard limits.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>On Node 22.23.1 for Linux x64 on an Intel Core i7-7820HQ, the committed <code>yarn workspace @jsvision/code-editor bench:architecture</code> run recorded 20 samples after five warmups:</p><table tabindex="0"><thead><tr><th>Fixture</th><th>Edit + viewport p50</th><th>Edit + viewport p95</th></tr></thead><tbody><tr><td>1 MiB</td><td>0.176 ms</td><td>0.337 ms</td></tr><tr><td>50,000 lines</td><td>0.129 ms</td><td>0.190 ms</td></tr></tbody></table><p>The isolated process used <code>--expose-gc</code>: baseline heap was 6,065,984 bytes, peak working heap was 11,429,560 bytes, and post-disposal heap was 6,183,184 bytes, for 117,200 peak retained bytes above baseline. Raw samples and the complete environment record are committed with the benchmark.</p><p>All supported built entry points imported in separate processes without DOM globals, process imports, or unrelated parser imports. A deterministic priority scheduler interleaved interactive updates with bounded parser, diagnostic, and completion slices; generation-cancelled results did not reach its presentation sink. The complete versioned production dependency closure contained only explicitly reviewed runtime packages, no DOM/browser/IDE runtime, and MIT-compatible declared licenses.</p><p>These measurements are environment evidence, not universal timing constants. Regression checks must retain deterministic fixtures and record runtime and platform alongside latency and memory.</p><h3 id="document-engine-evidence" tabindex="-1">Document engine evidence <a class="header-anchor" href="#document-engine-evidence" aria-label="Permalink to &quot;Document engine evidence&quot;">​</a></h3><p>The document engine normalizes untrusted transactions into opaque immutable records before application. It validates branded UTF-16 coordinates, exact CR/LF/CRLF logical-line deltas, document bytes, replacement bytes, and retained-history bytes before constructing changed storage. Undo and redo retain reversible change sets and changed content instead of full document snapshots.</p><p>The isolated Node 22.23.1 document benchmark used warmups, 20 measured samples, and explicit garbage collection:</p><table tabindex="0"><thead><tr><th>Fixture</th><th>Edit p50</th><th>Edit p95</th><th>Warm visual p50</th><th>Warm visual p95</th><th>Retained history</th></tr></thead><tbody><tr><td>1 MiB</td><td>0.618 ms</td><td>2.218 ms</td><td>0.509 ms</td><td>0.611 ms</td><td>2,000 bytes</td></tr><tr><td>50,000 lines</td><td>0.042 ms</td><td>0.084 ms</td><td>0.008 ms</td><td>0.015 ms</td><td>2,000 bytes</td></tr></tbody></table><p>The one-mebibyte fixture retained 2,285,392 heap bytes after 1,000 edits; the 50,000-line fixture retained 1,509,112 heap bytes. Raw samples, cold visual-column timings, runtime details, and platform details are committed with the benchmark evidence.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Root and optional entry points remain usable in a clean terminal Node runtime.</li><li>JavaScript, TypeScript, PostgreSQL, and LSP support do not require browser or IDE internals.</li><li>The document model and each parser remain replaceable behind editor-owned contracts.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>PostgreSQL cannot reuse Lezer incremental fragments and needs its own bounded scheduling path.</li><li>Adapter code must normalize different parser outputs into one syntax and structure model.</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>Reopen the PostgreSQL parser choice if measured synchronous calls breach the interaction budget.</li><li>Reopen the document model if later transaction, mapping, or retained-memory probes fail.</li><li>Re-run dependency and license closure checks whenever runtime dependencies change.</li></ul>',33)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
